# Generated by hyrax:models:install
class FileSet < ActiveFedora::Base

  # properties must go before include Morphosource::FileSetBehavior
  property :accessibility, predicate: ::RDF::URI.new("https://www.morphosource.org/terms/accessibility")
  property :mime_type_of_remote, predicate: ::RDF::URI.new("https://www.morphosource.org/terms/mimeTypeOfRemote"), multiple: false
  property :digest, predicate: ::RDF::URI.new("https://www.morphosource.org/terms/digest"), multiple: false
  property :e_tag, predicate: ::RDF::URI.new("https://www.morphosource.org/terms/ETag"), multiple: false

  include Morphosource::FileSetBehavior

  # ── FileSetSizeInfo integration ────────────────────────────────────────────

  # data_allocation_id is authoritative in FileSetSizeInfo; this reader avoids
  # an extra Fedora property by going directly to the AR table.
  def data_allocation_id
    FileSetSizeInfo.find_by(file_set_id: id.to_s)&.data_allocation_id
  end

  # AR-backed method to create or update this FileSet's FileSetSizeInfo row.
  def update_size_info(attrs = {})
    FileSetSizeInfo.upsert_for_file_set(self, attrs)
  end

  # Transactional lifecycle: ensure the FileSetSizeInfo row exists whenever
  # this FileSet is created, and is destroyed when the FileSet is destroyed.
  after_create  :create_size_info_row
  after_destroy :destroy_size_info_row

  # MS_CUSTOMIZATION : override FileSetIndexer
  #self.indexer = ::FileSetIndexer
  self.indexer = ::MsFileSetIndexer

  # for all file types
  delegate(
    :crc32,
    to: :characterization_proxy
  )

  # for images
  delegate(
    :bits_per_sample,
    :color_space,
    :compression,
    :focal_length,
    :aperture_value,
    :iso_speed_ratings,
    :shutter_speed,
    to: :characterization_proxy
    )

  # for dicom
  delegate(
    :spacing_between_slices,
    :modality,
    :secondary_capture_device_manufacturer,
    :secondary_capture_device_software_vers,
    :file_type_extension,
    :image_type,
    :study_date,
    :series_date,
    :content_date,
    :study_time,
    :series_time,
    :content_time,
    :accession_number,
    :instance_number,
    :image_position_patient,
    :image_orientation_patient,
    :samples_per_pixel,
    :photometric_interpretation,
    :rows,
    :columns,
    :pixel_spacing,
    :slice_thickness,
    :bits_allocated,
    :bits_stored,
    :high_bit,
    :pixel_representation,
    :window_center,
    :window_width,
    :rescale_intercept,
    :rescale_slope,
    :window_center_and_width_explanation,

    :exposure_time,
    :pixel_spacing_calibration_type,
    :contrast_frame_averaging,
    :images_in_acquisition,
    :KVP,
    :generator_power,
    :x_ray_tube_current,
    :container_description,
    :generator_id,
    :detector_description,
    :distance_source_to_patient,
    :distance_source_to_detector,
    :anode_target_material,
    :spiral_pitch_factor,
    :number_of_series_related_instances,
    to: :characterization_proxy
  )

  # for mesh
  delegate(
    :point_count,
    :face_count,
    :edges_per_face,
    :bounding_box_x,
    :bounding_box_y,
    :bounding_box_z,
    :centroid_x,
    :centroid_y,
    :centroid_z,
    :color_format,
    :normals_format,
    :has_uv_space,
    :vertex_color,
    :centroid_method,
    :blender_version,
    :gltf_inspect_version,
    :pymeshlab_version,
    to: :characterization_proxy
  )

  # for zip archive contents
  delegate(
    :contents_all_files,
    :contents_mime_type,
    :contents_file_name,
    :contents_file_size,
    :contents_accepted_file_count,
    to: :characterization_proxy
  )

  def media?
    false
  end

  private

  def create_size_info_row
    FileSetSizeInfo.upsert_for_file_set(self)
  rescue => e
    # Do not re-raise — FileSet is already persisted in Fedora at this point.
    # The listener's on_object_deposited provides a second chance to create the row.
    Rails.logger.error "Failed to create FileSetSizeInfo for FileSet #{id}: #{e.message}"
  end

  def destroy_size_info_row
    FileSetSizeInfo.find_by(file_set_id: id.to_s)&.destroy
  end

  public

  def processing_event?
    false
  end

  # this method is called after CharacterizeJob and CreateDerivativesJob
  def set_final_attributes
    if is_remote_backed?
      if (!self.mime_type_of_remote.present?) || (self.mime_type_of_remote.include? "message/external-body")
        self.mime_type_of_remote = characterization_proxy.mime_type
        characterization_proxy.mime_type = "message/external-body; access-type=URL; URL=\"#{import_url}\""
        characterization_proxy.save
        self.save
      end
      # set_remote_file_health after content_length is set
      self.parent.set_remote_file_health
    end
  end

  def is_remote_backed?
    return false unless self.parent.present?
    return self.parent.is_remote_backed?
  end

  def has_remote_manifest?
    return false unless self.parent.present?
    return self.parent.has_remote_manifest?
  end

  def remote_manifest_url
    self.parent&.remote_manifest_url
  end

  def remote_origin_url
    self.parent&.remote_origin_url
  end
end
